from ortools.sat.python import cp_model
import math
import json

def main():
    T = 2
    N = 10
    hub_x, hub_y = 30.0, 40.0

    loc_names = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon', 'Zeta', 'Eta', 'Theta', 'Iota', 'Kappa']
    loc_x = [37.0, 49.0, 52.0, 20.0, 40.0, 21.0, 17.0, 31.0, 52.0, 51.0]
    loc_y = [52.0, 49.0, 64.0, 26.0, 30.0, 47.0, 63.0, 62.0, 33.0, 21.0]
    demand = [7.0, 30.0, 16.0, 9.0, 21.0, 15.0, 19.0, 23.0, 11.0, 5.0]

    M1 = 2
    M2 = 3
    capacity = 160.0

    dist = [[0.0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if i != j:
                dx = loc_x[i] - loc_x[j]
                dy = loc_y[i] - loc_y[j]
                dist[i][j] = math.sqrt(dx*dx + dy*dy)

    dist_hub = [0.0] * N
    for i in range(N):
        dx = loc_x[i] - hub_x
        dy = loc_y[i] - hub_y
        dist_hub[i] = math.sqrt(dx*dx + dy*dy)

    model = cp_model.CpModel()

    max_routes_day1 = M1
    max_routes_day2 = M2

    assign = [[model.NewBoolVar(f"assign_{i}_{t}") for t in range(T)] for i in range(N)]

    route_exists = []
    for t in range(T):
        max_k = max_routes_day1 if t == 0 else max_routes_day2
        route_exists.append([model.NewBoolVar(f"route_exists_{t}_{k}") for k in range(max_k)])

    visit = []
    for i in range(N):
        day_visits = []
        for t in range(T):
            max_k = max_routes_day1 if t == 0 else max_routes_day2
            day_visits.append([model.NewBoolVar(f"visit_{i}_{t}_{k}") for k in range(max_k)])
        visit.append(day_visits)

    x = []
    for t in range(T):
        max_k = max_routes_day1 if t == 0 else max_routes_day2
        day_x = []
        for k in range(max_k):
            route_x = []
            for i in range(N + 1):
                node_x = []
                for j in range(N + 1):
                    node_x.append(model.NewBoolVar(f"x_{i}_{j}_{t}_{k}"))
                route_x.append(node_x)
            day_x.append(route_x)
        x.append(day_x)

    u = []
    for i in range(N + 1):
        day_u = []
        for t in range(T):
            max_k = max_routes_day1 if t == 0 else max_routes_day2
            day_u.append([model.NewIntVar(0, N, f"u_{i}_{t}_{k}") for k in range(max_k)])
        u.append(day_u)

    for i in range(5):
        model.Add(assign[i][0] + assign[i][1] == 1)

    model.Add(assign[5][0] == 1)
    model.Add(assign[5][1] == 1)
    model.Add(assign[6][0] == 1)
    model.Add(assign[6][1] == 1)

    model.Add(assign[7][0] == 1)
    model.Add(assign[7][1] == 0)

    model.Add(assign[8][0] == 0)
    model.Add(assign[8][1] == 1)
    model.Add(assign[9][0] == 0)
    model.Add(assign[9][1] == 1)

    model.Add(sum(route_exists[0][k] for k in range(max_routes_day1)) <= M1)
    model.Add(sum(route_exists[1][k] for k in range(max_routes_day2)) <= M2)

    scaled_demand = [int(d * 10) for d in demand]
    scaled_capacity = int(capacity * 10)

    for t in range(T):
        max_k = max_routes_day1 if t == 0 else max_routes_day2
        for k in range(max_k):
            total_demand = sum(scaled_demand[i] * visit[i][t][k] for i in range(N))
            model.Add(total_demand <= scaled_capacity)

    for i in range(N):
        for t in range(T):
            max_k = max_routes_day1 if t == 0 else max_routes_day2
            model.Add(assign[i][t] == sum(visit[i][t][k] for k in range(max_k)))

    for t in range(T):
        max_k = max_routes_day1 if t == 0 else max_routes_day2
        for k in range(max_k):
            for i in range(N):
                model.Add(visit[i][t][k] <= route_exists[t][k])
            model.Add(route_exists[t][k] <= sum(visit[i][t][k] for i in range(N)))

    for t in range(T):
        max_k = max_routes_day1 if t == 0 else max_routes_day2
        for k in range(max_k):
            model.Add(sum(x[t][k][0][j] for j in range(1, N + 1)) == route_exists[t][k])
            model.Add(sum(x[t][k][j][0] for j in range(1, N + 1)) == route_exists[t][k])

    for t in range(T):
        max_k = max_routes_day1 if t == 0 else max_routes_day2
        for k in range(max_k):
            for i in range(1, N + 1):
                loc_idx = i - 1
                model.Add(sum(x[t][k][i][j] for j in range(N + 1)) == visit[loc_idx][t][k])
                model.Add(sum(x[t][k][j][i] for j in range(N + 1)) == visit[loc_idx][t][k])

    for t in range(T):
        max_k = max_routes_day1 if t == 0 else max_routes_day2
        for k in range(max_k):
            for i in range(N + 1):
                model.Add(x[t][k][i][i] == 0)

    for t in range(T):
        max_k = max_routes_day1 if t == 0 else max_routes_day2
        for k in range(max_k):
            for i in range(1, N + 1):
                for j in range(1, N + 1):
                    if i != j:
                        model.Add(u[i][t][k] - u[j][t][k] + N * x[t][k][i][j] <= N - 1)

    scaled_dist_hub = [int(d * 100) for d in dist_hub]
    scaled_dist = [[int(d * 100) for d in row] for row in dist]

    total_distance = 0
    for t in range(T):
        max_k = max_routes_day1 if t == 0 else max_routes_day2
        for k in range(max_k):
            for j in range(1, N + 1):
                loc_idx = j - 1
                total_distance += x[t][k][0][j] * scaled_dist_hub[loc_idx]

            for i in range(1, N + 1):
                loc_idx = i - 1
                total_distance += x[t][k][i][0] * scaled_dist_hub[loc_idx]

            for i in range(1, N + 1):
                for j in range(1, N + 1):
                    if i != j:
                        loc_i_idx = i - 1
                        loc_j_idx = j - 1
                        total_distance += x[t][k][i][j] * scaled_dist[loc_i_idx][loc_j_idx]

    model.Minimize(total_distance)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 60.0
    solver.parameters.num_search_workers = 8
    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        location_delivery_schedules = []
        for i in range(N):
            schedule = []
            for t in range(T):
                schedule.append(1 if solver.Value(assign[i][t]) == 1 else 0)
            location_delivery_schedules.append(schedule)

        drone_flight_paths = []
        for t in range(T):
            max_k = max_routes_day1 if t == 0 else max_routes_day2
            day_paths = []
            for k in range(max_k):
                if solver.Value(route_exists[t][k]) == 1:
                    path = [0]
                    current_node = 0
                    visited = set()
                    while True:
                        next_node = None
                        for j in range(N + 1):
                            if solver.Value(x[t][k][current_node][j]) == 1 and j not in visited:
                                next_node = j
                                break
                        if next_node is None or next_node == 0:
                            path.append(0)
                            break
                        else:
                            path.append(next_node)
                            visited.add(next_node)
                            current_node = next_node
                    day_paths.append(path)
            drone_flight_paths.append(day_paths)

        total_flight_distance = solver.ObjectiveValue() / 100.0

        print(json.dumps({
            "location_delivery_schedules": location_delivery_schedules,
            "drone_flight_paths": drone_flight_paths,
            "total_flight_distance": total_flight_distance
        }))
    else:
        print(json.dumps({
            "location_delivery_schedules": [],
            "drone_flight_paths": [],
            "total_flight_distance": 0.0
        }))

if __name__ == "__main__":
    main()
